function buildNsfwMessages(userPrompt, options = {}) {
  const taskType = options.taskType || '';

  // 中文注释：封面/立绘关键词提取属于“画图标签翻译”任务，不应注入小说正文破限、NSFW校准对话或用户可调NSFW模块。
  // 新版本此前把 imagetext 也走完整 buildNsfwMessages，容易让标签提取结果混入正文/破限/NSFW指令，进而导致生图接口拒绝或连接被关闭。
  if (taskType === 'imagetext') {
    return options.systemPrompt
      ? [{ role: 'system', content: options.systemPrompt }, { role: 'user', content: userPrompt }]
      : [{ role: 'user', content: userPrompt }];
  }

  const msgs = [];
  const safeState = { limit: 0 };

  if (novel.value.isAdultMode) {
    const nsfwPrompt = getFullNsfwSystemPrompt();
    if (nsfwPrompt) pushProtectedMessage(msgs, safeState, { role: 'system', content: nsfwPrompt });
    getDeepSeekPreludeMessages().forEach(message => pushProtectedMessage(msgs, safeState, message));
    getNsfwInjectionMessages().forEach(message => pushProtectedMessage(msgs, safeState, message));
  }

  if (options.systemPrompt) {
    msgs.push({ role: 'system', content: options.systemPrompt });
  }

  const nsfwEnhancementPrompt = getNsfwPrompt(taskType);
  if (nsfwEnhancementPrompt) {
    msgs.push({ role: 'system', content: '【用户可调NSFW效果增强】\n' + nsfwEnhancementPrompt });
  }

  msgs.push({ role: 'user', content: userPrompt });
  printAIRequestLogs(msgs, getModelForModule(taskType === 'outline' || taskType === 'detailedOutline' ? 'outline' : 'writing'), '通用请求 messages');
  return msgs;
}
